titles = input().split()
n = len(titles)
who = [""] * n
cnt = {}
while True:
    p = input().split()
    if p[0] == "끝":
        break
    if p[0] == "빌림":
        name = p[1]
        k = int(p[2])
        if k < 1 or k > n:
            print("없는 번호")
        elif who[k - 1] != "":
            print(f"대출 중 ({who[k - 1]})")
        elif cnt.get(name, 0) >= 2:
            print("권수 초과")
        else:
            who[k - 1] = name
            cnt[name] = cnt.get(name, 0) + 1
            print(f"{name}: {titles[k - 1]} 대출")
    elif p[0] == "반납":
        k = int(p[1])
        if k < 1 or k > n:
            print("없는 번호")
        elif who[k - 1] == "":
            print("대출 기록 없음")
        else:
            name = who[k - 1]
            who[k - 1] = ""
            cnt[name] -= 1
            print(f"{name}: {titles[k - 1]} 반납")
    else:
        key = p[1]
        out = []
        for i in range(n):
            t = titles[i]
            hit = False
            for j in range(len(t) - len(key) + 1):
                if t[j:j + len(key)] == key:
                    hit = True
                    break
            if hit:
                state = "가능"
                if who[i] != "":
                    state = who[i]
                out.append(f"{i + 1}.{t}({state})")
        if out:
            print(*out)
        else:
            print("검색 결과 없음")
shown = False
for name in cnt:
    if cnt[name] > 0:
        print(f"{name} {cnt[name]}권")
        shown = True
if not shown:
    print("모두 반납됨")
